
import type { OnboardingNextStep } from './OnboardingNextStep.js';
import type { OnboardingProfile } from './OnboardingProfile.js';
import type { OnboardingRequirements } from './OnboardingRequirements.js';

export type OnboardingState = { "available_actions"?: Array<OnboardingNextStep>; "can_issue_api_key": boolean; /** RFC3339 timestamp. Format: date-time. */ "capabilities_synced_at"?: string; /** Immutable business country for the selected stable provider-account target. Omitted until the target has selected an effective country. minLength: 2. maxLength: 2. pattern: ^[A-Z]{2}$. Example: "US". */ "country"?: "US" | (string & {}); "default_sandbox_id"?: string; "email_verified": boolean; "merchant_created": boolean; "merchant_id": string; "next_step"?: OnboardingNextStep; "pending_steps"?: Array<OnboardingNextStep>; "profile": OnboardingProfile; /** RFC3339 timestamp. Format: date-time. */ "readiness_observed_at"?: string; /** Canonical Flint capability intent persisted on the selected stable provider-account target. The initial merchant-account configuration always includes accept_card_payments and receive_payouts and may also include accept_ach_debit_payments. */ "requested_capabilities"?: ((Array<"accept_card_payments" | "receive_payouts" | (string & {})>) | (Array<"accept_ach_debit_payments" | "accept_card_payments" | "receive_payouts" | (string & {})>) | (unknown)); "requirements": OnboardingRequirements; /** Onboarding workflow status for activation and remediation, not a durable account-readiness boolean. */ "status": string; };
